import { useQuery, type UseQueryOptions } from "@tanstack/react-query";
import { listReports } from "../handlers/listReports";
import type { ApiError } from "../runtime/client";
import type { ReportStatus } from "../types/ReportStatus";
import type { SpacePartition } from "../types/SpacePartition";

type Data = Awaited<ReturnType<typeof listReports>>;

export function useListReports(
  spacePk: SpacePartition,
  bookmark?: string | null,
  status?: ReportStatus | null,
  options?: Omit<UseQueryOptions<Data, ApiError>, "queryKey" | "queryFn">,
) {
  return useQuery<Data, ApiError>({
    queryKey: ["listReports", spacePk, bookmark, status],
    queryFn: () => listReports(spacePk, bookmark, status),
    ...options,
  });
}
